using System.Security.Claims;using System.Text;using EmployeeMonitoringAPI.Data;using EmployeeMonitoringAPI.Interfaces;using EmployeeMonitoringAPI.Models;using EmployeeMonitoringAPI.Services;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace EmployeeMonitoringAPI.Controllers;
[ApiController][Route("api/hr")][Authorize(Roles="HR")]
public sealed class HrOperationsController:ControllerBase
{
 readonly ApplicationDbContext db;readonly PasswordService passwords;readonly IAuditService audit;public HrOperationsController(ApplicationDbContext db,PasswordService passwords,IAuditService audit){this.db=db;this.passwords=passwords;this.audit=audit;}int HrId()=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);IQueryable<User> People(string? role=null)=>db.Users.Where(x=>x.AssignedHrId==HrId()&&(x.Role=="Employee"||x.Role=="Manager")&&(role==null||x.Role==role));Task<User?> Person(int id,string? role=null)=>People(role).Include(x=>x.Department).FirstOrDefaultAsync(x=>x.UserId==id);
 [HttpGet("dashboard")]public async Task<IActionResult> Dashboard(){var h=HrId();var p=People();var recent=await p.OrderByDescending(x=>x.CreatedAt).Take(6).Select(x=>new{x.UserId,x.FullName,x.Role,x.IsActive,x.EmploymentStatus,x.CreatedAt}).ToListAsync();var pipeline=await db.Applicants.Where(x=>x.AssignedHrId==h).GroupBy(x=>x.Status).Select(x=>new{status=x.Key,count=x.Count()}).ToListAsync();var on=await db.OnboardingRecords.Where(x=>x.AssignedHrId==h&&x.Status!="Completed"&&x.Status!="Cancelled").OrderBy(x=>x.JoiningDate).Take(5).ToListAsync();var off=await db.OffboardingRecords.Where(x=>x.AssignedHrId==h&&x.Status!="Completed"&&x.Status!="Cancelled").OrderBy(x=>x.LastWorkingDate).Take(5).Select(x=>new{x.OffboardingId,x.UserId,userName=db.Users.Where(u=>u.UserId==x.UserId).Select(u=>u.FullName).FirstOrDefault(),x.LastWorkingDate,x.Status}).ToListAsync();var notes=await db.Notifications.Where(x=>x.UserId==h).OrderByDescending(x=>x.CreatedAt).Take(6).Select(x=>new{x.Id,x.Title,x.Message,x.Type,x.IsRead,x.CreatedAt,x.RelatedUrl}).ToListAsync();return Ok(new{totalEmployees=await p.CountAsync(x=>x.Role=="Employee"),totalManagers=await p.CountAsync(x=>x.Role=="Manager"),activeEmployees=await p.CountAsync(x=>x.Role=="Employee"&&x.IsActive),activeManagers=await p.CountAsync(x=>x.Role=="Manager"&&x.IsActive),openJobPositions=await db.RecruitmentJobs.CountAsync(x=>x.AssignedHrId==h&&x.Status=="Open"),pendingApplicants=await db.Applicants.CountAsync(x=>x.AssignedHrId==h&&!new[]{"Selected","Rejected","Withdrawn"}.Contains(x.Status)),pendingOnboarding=on.Count,pendingOffboarding=off.Count,unreadNotifications=await db.Notifications.CountAsync(x=>x.UserId==h&&!x.IsRead),recentEmployeeActivity=recent,recruitmentPipeline=pipeline,upcomingOnboarding=on,upcomingOffboarding=off,employeesRequiringAttention=await p.Where(x=>!x.IsActive||x.DepartmentId==null||(x.Role=="Employee"&&x.ManagerId==null)).Take(6).Select(x=>new{x.UserId,x.FullName,x.Role,reason=!x.IsActive?"Inactive account":x.DepartmentId==null?"Department missing":"Manager missing"}).ToListAsync(),recentNotifications=notes});}
 [HttpGet("options")]public async Task<IActionResult> Options()=>Ok(new{departments=await db.Departments.Where(x=>x.IsActive).OrderBy(x=>x.Name).Select(x=>new{departmentId=x.Id,x.Name}).ToListAsync(),managers=await People("Manager").Where(x=>x.IsActive).Select(x=>new{x.UserId,x.FullName,x.EmployeeCode,x.DepartmentId}).ToListAsync(),people=await People().OrderBy(x=>x.FullName).Select(x=>new{x.UserId,x.FullName,x.Role,x.EmployeeCode,x.IsActive}).ToListAsync()});
 [HttpGet("people")]public async Task<IActionResult> GetPeople(string role="Employee",string? search=null,string? status=null,int? departmentId=null,int? managerId=null,string sort="name",int page=1,int pageSize=10){if(role is not("Employee"or"Manager"))return BadRequest(new{message="Invalid role"});page=Math.Max(1,page);pageSize=Math.Clamp(pageSize,5,100);var q=People(role).Include(x=>x.Department).Include(x=>x.Manager).AsQueryable();if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.FullName.Contains(search)||x.Email.Contains(search)||x.Username.Contains(search)||(x.EmployeeCode??"").Contains(search));if(status=="Active")q=q.Where(x=>x.IsActive);if(status=="Inactive")q=q.Where(x=>!x.IsActive);if(departmentId.HasValue)q=q.Where(x=>x.DepartmentId==departmentId);if(managerId.HasValue)q=q.Where(x=>x.ManagerId==managerId);q=sort=="joining"?q.OrderByDescending(x=>x.DateOfJoining):sort=="code"?q.OrderBy(x=>x.EmployeeCode):q.OrderBy(x=>x.FullName);var total=await q.CountAsync();var items=await q.Skip((page-1)*pageSize).Take(pageSize).Select(x=>new{x.UserId,x.FullName,x.EmployeeCode,x.Email,x.Username,x.PhoneNumber,department=x.Department!=null?x.Department.Name:null,x.DepartmentId,x.Designation,managerName=x.Manager!=null?x.Manager.FullName:null,x.ManagerId,x.EmploymentType,x.WorkLocation,x.DateOfJoining,x.EmploymentStatus,x.IsActive,teamMemberCount=role=="Manager"?db.Users.Count(u=>u.ManagerId==x.UserId&&u.AssignedHrId==HrId()):0}).ToListAsync();return Ok(new{items,totalCount=total,page,pageSize,totalPages=(int)Math.Ceiling(total/(double)pageSize)});}
 [HttpGet("people/{id:int}")]public async Task<IActionResult> GetPerson(int id){var x=await Person(id);if(x==null)return NotFound();return Ok(new{person=new{x.UserId,x.FullName,x.EmployeeCode,x.Email,x.Username,x.PhoneNumber,x.Designation,x.DepartmentId,department=x.Department?.Name,x.ManagerId,x.EmploymentType,x.WorkLocation,x.DateOfJoining,x.EmploymentStatus,x.IsActive,x.Role},attendance=await db.Attendances.Where(a=>a.UserId==id).OrderByDescending(a=>a.AttendanceDate).Take(10).ToListAsync(),leaves=await db.Leaves.Where(a=>a.UserId==id).OrderByDescending(a=>a.AppliedAt).Take(10).ToListAsync(),training=await db.TrainingAssignments.Where(a=>a.UserId==id).Select(a=>new{a.TrainingProgramId,a.Status}).ToListAsync(),performance=await db.PerformanceReviews.Where(a=>a.EmployeeId==id).OrderByDescending(a=>a.Year).Select(a=>new{a.Year,a.Quarter,a.Rating,a.IsReleased}).ToListAsync()});}
 [HttpPost("people")]public async Task<IActionResult>CreatePerson(HrRequest r){if(r.Role is not("Employee"or"Manager"))return BadRequest(new{message="HR may create only Employee or Manager"});if(string.IsNullOrWhiteSpace(r.Password)||r.Password.Length<8)return BadRequest(new{message="Temporary password must contain at least 8 characters"});if(await db.Users.AnyAsync(x=>x.Email==r.Email||x.Username==r.Username||x.EmployeeCode==r.EmployeeCode))return Conflict(new{message="Email, username or code already exists"});if(r.DepartmentId.HasValue&&!await db.Departments.AnyAsync(x=>x.Id==r.DepartmentId&&x.IsActive))return BadRequest(new{message="Select an active department"});if(r.Role=="Employee"&&r.ManagerId.HasValue&&!await People("Manager").AnyAsync(x=>x.UserId==r.ManagerId&&x.IsActive))return StatusCode(403,new{message="Manager is outside your scope or inactive"});var x=new User{FullName=r.FullName.Trim(),Email=r.Email.Trim(),Username=r.Username.Trim(),EmployeeCode=r.EmployeeCode.Trim(),PasswordHash=passwords.HashPassword(r.Password),Role=r.Role,AssignedHrId=HrId(),DepartmentId=r.DepartmentId,ManagerId=r.Role=="Employee"?r.ManagerId:null,PhoneNumber=r.PhoneNumber,Designation=r.Designation,DateOfJoining=r.JoiningDate,EmploymentType=r.EmploymentType,EmploymentStatus="Active",WorkLocation=r.Location,IsActive=r.IsActive};db.Users.Add(x);await db.SaveChangesAsync();await audit.RecordAsync("HrPersonCreated","User",x.UserId.ToString(),actorUserId:HrId(),safeMetadata:new{x.Role});return Ok(new{message=$"{x.Role} created",x.UserId});}
 [HttpPut("people/{id:int}")]public async Task<IActionResult>UpdatePerson(int id,HrRequest r){var x=await Person(id);if(x==null)return NotFound();if(r.ManagerId.HasValue&&!await People("Manager").AnyAsync(m=>m.UserId==r.ManagerId&&m.IsActive))return StatusCode(403);x.FullName=r.FullName.Trim();x.PhoneNumber=r.PhoneNumber;x.DepartmentId=r.DepartmentId;x.ManagerId=x.Role=="Employee"?r.ManagerId:null;x.Designation=r.Designation;x.DateOfJoining=r.JoiningDate;x.EmploymentType=r.EmploymentType;x.WorkLocation=r.Location;x.EmploymentStatus=r.EmploymentStatus;await db.SaveChangesAsync();return Ok(new{message="Employment record updated"});}
 [HttpPatch("people/{id:int}/status")]public async Task<IActionResult>Status(int id,HrRequest r){var x=await Person(id);if(x==null)return NotFound();x.IsActive=r.IsActive;x.EmploymentStatus=r.IsActive?"Active":"Inactive";if(!r.IsActive)await InvalidateMfa(id);await db.SaveChangesAsync();return Ok(new{message=r.IsActive?"Account activated":"Account deactivated"});}
 [HttpPut("people/{id:int}/manager")]public async Task<IActionResult>AssignManager(int id,HrRequest r){await using var t=await db.Database.BeginTransactionAsync();var e=await Person(id,"Employee");var m=await Person(r.ManagerId??0,"Manager");if(e==null||m==null)return NotFound();if(!e.IsActive||!m.IsActive)return Conflict(new{message="Both users must be active"});if(e.ManagerId==m.UserId)return Conflict(new{message="Already assigned"});e.ManagerId=m.UserId;Notify(e.UserId,"Manager changed",$"Your reporting Manager is now {m.FullName}.","ManagerAssignment","/employee/dashboard",$"manager:{e.UserId}:{m.UserId}:{DateTime.UtcNow.Ticks}");Notify(m.UserId,"Employee assigned",$"{e.FullName} joined your team.","ManagerAssignment","/manager/team",$"team:{m.UserId}:{e.UserId}:{DateTime.UtcNow.Ticks}");await db.SaveChangesAsync();await t.CommitAsync();return Ok(new{message="Assignment updated; history preserved"});} [NonAction][HttpGet("jobs")]public async Task<IActionResult>Jobs()=>Ok(await db.RecruitmentJobs.Where(x=>x.AssignedHrId==HrId()).OrderByDescending(x=>x.CreatedAt).ToListAsync());
 [NonAction][HttpPost("jobs")]public async Task<IActionResult>CreateJob(HrRequest r){if(r.ClosingDate.HasValue&&r.ClosingDate<r.OpeningDate)return BadRequest(new{message="Closing date cannot precede opening date"});if(await db.RecruitmentJobs.AnyAsync(x=>x.AssignedHrId==HrId()&&x.JobCode==r.JobCode))return Conflict(new{message="Job code exists"});var x=new RecruitmentJob{AssignedHrId=HrId()};Job(x,r);db.Add(x);await db.SaveChangesAsync();return Ok(new{message="Job opening created",x.JobId});}
 [NonAction][HttpPut("jobs/{id:int}")]public async Task<IActionResult>UpdateJob(int id,HrRequest r){var x=await db.RecruitmentJobs.FirstOrDefaultAsync(j=>j.JobId==id&&j.AssignedHrId==HrId());if(x==null)return NotFound();if(r.ClosingDate.HasValue&&r.ClosingDate<r.OpeningDate)return BadRequest(new{message="Invalid dates"});Job(x,r);await db.SaveChangesAsync();return Ok(new{message="Job opening updated"});}
 [NonAction][HttpGet("applicants")]public async Task<IActionResult>Applicants()=>Ok(await db.Applicants.Where(x=>x.AssignedHrId==HrId()).OrderByDescending(x=>x.AppliedAt).Select(x=>new{x.ApplicantId,x.JobId,jobTitle=db.RecruitmentJobs.Where(j=>j.JobId==x.JobId).Select(j=>j.Title).FirstOrDefault(),x.FullName,x.Email,x.Phone,x.ResumeUrl,x.Experience,x.Remarks,x.Status,x.AppliedAt}).ToListAsync());
 [NonAction][HttpPost("applicants")]public async Task<IActionResult>CreateApplicant(HrRequest r){var job=await db.RecruitmentJobs.FirstOrDefaultAsync(x=>x.JobId==r.JobId&&x.AssignedHrId==HrId());if(job==null)return NotFound();if(new[]{"Closed","Cancelled","Filled"}.Contains(job.Status))return Conflict(new{message="Opening is not accepting applications"});if(await db.Applicants.AnyAsync(x=>x.AssignedHrId==HrId()&&x.JobId==r.JobId&&x.Email==r.Email))return Conflict(new{message="Duplicate application"});var x=new Applicant{AssignedHrId=HrId(),JobId=r.JobId,FullName=r.FullName,Email=r.Email,Phone=r.PhoneNumber??"",ResumeUrl=r.ResumeUrl??"",Experience=r.Experience??"",Remarks=r.Remarks??"",Status="Applied"};db.Add(x);await db.SaveChangesAsync();return Ok(new{message="Applicant added",x.ApplicantId});}
 [NonAction][HttpPut("applicants/{id:int}")]public async Task<IActionResult>UpdateApplicant(int id,HrRequest r){var x=await db.Applicants.FirstOrDefaultAsync(a=>a.ApplicantId==id&&a.AssignedHrId==HrId());if(x==null)return NotFound();x.Status=r.Status;x.Remarks=r.Remarks??"";x.Experience=r.Experience??x.Experience;await db.SaveChangesAsync();return Ok(new{message="Applicant updated"});}
 [NonAction][HttpGet("interviews")]public async Task<IActionResult>Interviews()=>Ok(await db.Interviews.Where(x=>x.AssignedHrId==HrId()).OrderBy(x=>x.ScheduledAt).Select(x=>new{x.InterviewId,x.ApplicantId,applicantName=db.Applicants.Where(a=>a.ApplicantId==x.ApplicantId).Select(a=>a.FullName).FirstOrDefault(),x.InterviewerId,interviewerName=db.Users.Where(u=>u.UserId==x.InterviewerId).Select(u=>u.FullName).FirstOrDefault(),x.ScheduledAt,x.EndTime,x.Mode,x.Location,x.Status,x.Feedback,x.Result,x.Notes,x.HrRemarks}).ToListAsync());
 [NonAction][HttpPost("interviews")]public async Task<IActionResult>CreateInterview(HrRequest r){var v=await InterviewValid(r);if(v!=null)return v;var x=new Interview{AssignedHrId=HrId()};Interview(x,r);db.Add(x);await db.SaveChangesAsync();if(x.InterviewerId.HasValue){Notify(x.InterviewerId.Value,"Interview scheduled",$"Interview scheduled for {x.ScheduledAt:g}.","Interview","/manager/calendar",$"interview:{x.InterviewId}:{x.InterviewerId}");await db.SaveChangesAsync();}return Ok(new{message="Interview scheduled",x.InterviewId});}
 [NonAction][HttpPut("interviews/{id:int}")]public async Task<IActionResult>UpdateInterview(int id,HrRequest r){var x=await db.Interviews.FirstOrDefaultAsync(i=>i.InterviewId==id&&i.AssignedHrId==HrId());if(x==null)return NotFound();if(r.EndTime<=r.StartTime)return BadRequest(new{message="End must be after start"});Interview(x,r);await db.SaveChangesAsync();return Ok(new{message="Interview updated"});}
 [HttpGet("onboarding")]public async Task<IActionResult>Onboarding()=>Ok(await db.OnboardingRecords.Where(x=>x.AssignedHrId==HrId()).OrderBy(x=>x.JoiningDate).ToListAsync());
 [HttpPost("onboarding")]public async Task<IActionResult>CreateOnboarding(HrRequest r){if(r.ApplicantId.HasValue&&!await db.Applicants.AnyAsync(x=>x.ApplicantId==r.ApplicantId&&x.AssignedHrId==HrId()&&x.Status=="Selected"))return Conflict(new{message="Only selected candidates may be onboarded"});var x=new OnboardingRecord{AssignedHrId=HrId()};Onboard(x,r);db.Add(x);await db.SaveChangesAsync();return Ok(new{message="Onboarding started",x.OnboardingId});}
