 [HttpPost("onboarding/{id:int}/complete")]public async Task<IActionResult>CompleteOnboarding(int id,HrRequest r){await using var t=await db.Database.BeginTransactionAsync();var x=await db.OnboardingRecords.FirstOrDefaultAsync(o=>o.OnboardingId==id&&o.AssignedHrId==HrId());if(x==null)return NotFound();if(x.Status=="Completed")return Conflict(new{message="Already completed"});var u=x.EmployeeId.HasValue?await Person(x.EmployeeId.Value):null;if(u==null){if(string.IsNullOrWhiteSpace(r.Username)||r.Password.Length<8||string.IsNullOrWhiteSpace(x.OfficialEmail)||string.IsNullOrWhiteSpace(x.EmployeeCode))return BadRequest(new{message="Username, secure temporary password, email and code are required"});if(await db.Users.AnyAsync(z=>z.Email==x.OfficialEmail||z.Username==r.Username||z.EmployeeCode==x.EmployeeCode))return Conflict(new{message="Account identifiers exist"});u=new User{FullName=x.CandidateName,Email=x.OfficialEmail,Username=r.Username,EmployeeCode=x.EmployeeCode,PasswordHash=passwords.HashPassword(r.Password),Role=x.Role=="Manager"?"Manager":"Employee",AssignedHrId=HrId(),DepartmentId=x.DepartmentId,ManagerId=x.Role=="Employee"?x.ManagerId:null,Designation=x.Designation,DateOfJoining=x.JoiningDate,EmploymentType=x.EmploymentType,EmploymentStatus="Active",IsActive=true};db.Add(u);await db.SaveChangesAsync();x.EmployeeId=u.UserId;}else{u.IsActive=true;u.EmploymentStatus="Active";}x.Status="Completed";await db.SaveChangesAsync();await t.CommitAsync();return Ok(new{message="Onboarding completed",u.UserId});}
 [HttpGet("offboarding")]public async Task<IActionResult>Offboarding()=>Ok(await db.OffboardingRecords.Where(x=>x.AssignedHrId==HrId()).OrderBy(x=>x.LastWorkingDate).Select(x=>new{x.OffboardingId,x.UserId,userName=db.Users.Where(u=>u.UserId==x.UserId).Select(u=>u.FullName).FirstOrDefault(),x.ResignationDate,x.LastWorkingDate,x.Reason,x.ExitType,x.NoticePeriodDays,x.Status,x.Checklist,x.Remarks,x.AccountDeactivatedAt}).ToListAsync());
 [HttpPost("offboarding")]public async Task<IActionResult>CreateOffboarding(HrRequest r){var u=await Person(r.UserId);if(u==null)return NotFound();if(r.LastWorkingDate<r.ResignationDate)return BadRequest(new{message="Invalid dates"});if(await db.OffboardingRecords.AnyAsync(x=>x.UserId==r.UserId&&x.Status!="Completed"&&x.Status!="Cancelled"))return Conflict(new{message="Active offboarding exists"});var x=new OffboardingRecord{AssignedHrId=HrId()};Offboard(x,r);db.Add(x);Notify(u.UserId,"Offboarding initiated","HR initiated your offboarding workflow.","Offboarding",null,$"offboard:{u.UserId}:start");await db.SaveChangesAsync();return Ok(new{message="Offboarding initiated",x.OffboardingId});}
 [HttpPut("offboarding/{id:int}")]public async Task<IActionResult>UpdateOffboarding(int id,HrRequest r){var x=await db.OffboardingRecords.FirstOrDefaultAsync(o=>o.OffboardingId==id&&o.AssignedHrId==HrId());if(x==null)return NotFound();Offboard(x,r);await db.SaveChangesAsync();return Ok(new{message="Offboarding updated"});}
 [HttpPost("offboarding/{id:int}/complete")]public async Task<IActionResult>CompleteOffboarding(int id){await using var t=await db.Database.BeginTransactionAsync();var x=await db.OffboardingRecords.FirstOrDefaultAsync(o=>o.OffboardingId==id&&o.AssignedHrId==HrId());if(x==null)return NotFound();if(x.Status=="Completed")return Conflict(new{message="Already completed"});var u=await Person(x.UserId);if(u==null)return NotFound();u.IsActive=false;u.EmploymentStatus="Offboarded";x.Status="Completed";x.AccountDeactivatedAt=DateTime.UtcNow;await InvalidateMfa(u.UserId);db.ActivityLogs.Add(new ActivityLog{UserId=u.UserId,Action="Offboarding completed and access revoked"});await db.SaveChangesAsync();await t.CommitAsync();await audit.RecordAsync("OffboardingCompleted","User",u.UserId.ToString(),actorUserId:HrId());return Ok(new{message="Account access revoked; history preserved"});} [HttpGet("attendance")]public async Task<IActionResult>Attendance(DateTime? from,DateTime? to,int? userId,int? managerId,int? departmentId,string? status){var start=(from??DateTime.UtcNow.Date).Date;var end=(to??start).Date.AddDays(1);var q=db.Attendances.Include(x=>x.User).ThenInclude(x=>x!.Manager).Where(x=>x.User!.AssignedHrId==HrId()&&x.AttendanceDate>=start&&x.AttendanceDate<end);if(userId.HasValue)q=q.Where(x=>x.UserId==userId);if(managerId.HasValue)q=q.Where(x=>x.User!.ManagerId==managerId);if(departmentId.HasValue)q=q.Where(x=>x.User!.DepartmentId==departmentId);if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.AttendanceStatus==status);return Ok(await q.OrderByDescending(x=>x.AttendanceDate).Select(x=>new{x.AttendanceId,x.UserId,userName=x.User!.FullName,x.User.EmployeeCode,x.AttendanceDate,x.CheckInTime,x.CheckOutTime,workingHours=x.EffectiveHours,x.BreakMinutes,x.LateMinutes,missingCheckout=x.CheckInTime!=null&&x.CheckOutTime==null,status=x.AttendanceStatus,managerName=x.User.Manager!=null?x.User.Manager.FullName:null}).ToListAsync());}
 [HttpGet("leaves")]public async Task<IActionResult>Leaves(int? userId,int? managerId,string? status){var q=db.Leaves.Include(x=>x.User).ThenInclude(x=>x!.Manager).Where(x=>x.User!.AssignedHrId==HrId());if(userId.HasValue)q=q.Where(x=>x.UserId==userId);if(managerId.HasValue)q=q.Where(x=>x.User!.ManagerId==managerId);if(!string.IsNullOrWhiteSpace(status))q=q.Where(x=>x.Status==status);return Ok(await q.OrderByDescending(x=>x.AppliedAt).Select(x=>new{x.LeaveId,x.UserId,userName=x.User!.FullName,x.LeaveType,x.FromDate,x.ToDate,workingDays=x.IsHalfDay?.5:Math.Max(1,EF.Functions.DateDiffDay(x.FromDate,x.ToDate)+1),duration=x.IsHalfDay?"Half Day":"Full Day",x.Status,managerName=x.User.Manager!=null?x.User.Manager.FullName:null,x.AppliedAt,decisionDate=x.ApprovedAt,managerRemarks=x.ApprovalRemarks,leaveBalance=db.LeaveBalances.Where(b=>b.UserId==x.UserId).Select(b=>b.TotalLeaves-b.UsedLeaves).FirstOrDefault()}).ToListAsync());}
 [HttpGet("training")]public async Task<IActionResult>Training()=>Ok(await db.TrainingPrograms.Where(x=>x.AssignedHrId==HrId()).Include(x=>x.Assignments).ThenInclude(x=>x.User).OrderByDescending(x=>x.StartDate).Select(x=>new{x.TrainingProgramId,x.Name,x.Code,x.Description,x.Trainer,x.DepartmentId,x.StartDate,x.EndDate,x.DeliveryMode,x.Location,x.Status,x.Remarks,assignments=x.Assignments.Select(a=>new{a.UserId,userName=a.User!.FullName,a.Status,a.Remarks,a.CompletedAt})}).ToListAsync());
 [HttpPost("training")]public async Task<IActionResult>CreateTraining(HrRequest r){if(r.EndTime<r.StartTime)return BadRequest(new{message="Invalid dates"});if(await db.TrainingPrograms.AnyAsync(x=>x.AssignedHrId==HrId()&&x.Code==r.Code))return Conflict(new{message="Training code exists"});var x=new TrainingProgram{AssignedHrId=HrId()};Train(x,r);db.Add(x);await db.SaveChangesAsync();return Ok(new{message="Training created",x.TrainingProgramId});}
 [HttpPut("training/{id:int}")]public async Task<IActionResult>UpdateTraining(int id,HrRequest r){var x=await db.TrainingPrograms.FirstOrDefaultAsync(t=>t.TrainingProgramId==id&&t.AssignedHrId==HrId());if(x==null)return NotFound();Train(x,r);await db.SaveChangesAsync();return Ok(new{message="Training updated"});}
 [HttpPost("training/{id:int}/assignments")]public async Task<IActionResult>AssignTraining(int id,HrRequest r){var x=await db.TrainingPrograms.FirstOrDefaultAsync(t=>t.TrainingProgramId==id&&t.AssignedHrId==HrId());var u=await Person(r.UserId);if(x==null||u==null)return NotFound();if(await db.TrainingAssignments.AnyAsync(a=>a.TrainingProgramId==id&&a.UserId==r.UserId))return Conflict(new{message="Already assigned"});db.Add(new TrainingAssignment{TrainingProgramId=id,UserId=r.UserId,Remarks=r.Remarks??""});Notify(r.UserId,"Training assigned",$"You were assigned to {x.Name}.","Training","/employee/performance",$"training:{id}:{r.UserId}");await db.SaveChangesAsync();return Ok(new{message="Training assigned"});}
 [HttpPut("training/{id:int}/assignments/{userId:int}")]public async Task<IActionResult>TrainingStatus(int id,int userId,HrRequest r){var x=await db.TrainingAssignments.FirstOrDefaultAsync(a=>a.TrainingProgramId==id&&a.UserId==userId&&a.TrainingProgram!.AssignedHrId==HrId());if(x==null)return NotFound();x.Status=r.Status;x.Remarks=r.Remarks??"";x.CompletedAt=r.Status=="Completed"?DateTime.UtcNow:null;await db.SaveChangesAsync();return Ok(new{message="Assignment updated"});}
 [HttpDelete("training/{id:int}/assignments/{userId:int}")]public async Task<IActionResult>RemoveTraining(int id,int userId){var x=await db.TrainingAssignments.FirstOrDefaultAsync(a=>a.TrainingProgramId==id&&a.UserId==userId&&a.TrainingProgram!.AssignedHrId==HrId());if(x==null)return NotFound();db.Remove(x);await db.SaveChangesAsync();return Ok(new{message="Assignment removed; account preserved"});}
 [HttpGet("performance")]public async Task<IActionResult>Performance(int? year,string quarter="Q1"){var y=year??DateTime.UtcNow.Year;if(quarter is not("Q1"or"Q2"or"Q3"or"Q4"))return BadRequest(new{message="Quarter must be Q1-Q4"});var month=quarter switch{"Q1"=>1,"Q2"=>4,"Q3"=>7,_=>10};var start=new DateTime(y,month,1);var end=start.AddMonths(3);var users=await People().Include(x=>x.Manager).OrderBy(x=>x.FullName).ToListAsync();var rows=new List<object>();foreach(var u in users){var tasks=await db.WorkTasks.Where(x=>x.AssignedToId==u.UserId&&x.CreatedAt<end&&(x.DueDate==null||x.DueDate>=start)).ToListAsync();var sheets=await db.WeeklyTimesheets.Include(x=>x.Lines).Where(x=>x.EmployeeId==u.UserId&&x.WeekStartDate>=start&&x.WeekStartDate<end).ToListAsync();var review=await db.PerformanceReviews.FirstOrDefaultAsync(x=>x.EmployeeId==u.UserId&&x.Year==y&&x.Quarter==quarter);rows.Add(new{u.UserId,u.FullName,u.Role,managerName=u.Manager?.FullName,year=y,quarter,projects=await db.ProjectAssignments.CountAsync(x=>x.UserId==u.UserId),tasksCompleted=tasks.Count(x=>x.Status=="Completed"),tasksPending=tasks.Count(x=>x.Status!="Completed"&&x.Status!="Cancelled"),tasksOverdue=tasks.Count(x=>x.DueDate<DateTime.UtcNow&&x.Status!="Completed"&&x.Status!="Cancelled"),timesheetHours=sheets.Sum(x=>x.TotalHours),billableHours=sheets.SelectMany(x=>x.Lines).Where(x=>x.BillingType=="Billable").Sum(x=>x.TotalHours),nonBillableHours=sheets.SelectMany(x=>x.Lines).Where(x=>x.BillingType!="Billable").Sum(x=>x.TotalHours),managerReviewStatus=review==null?"Not submitted":review.IsReleased?"Released":"Draft",managerRating=review?.Rating,trainingCompleted=await db.TrainingAssignments.CountAsync(x=>x.UserId==u.UserId&&x.Status=="Completed"&&x.CompletedAt>=start&&x.CompletedAt<end)});}return Ok(rows);}
 [HttpGet("reports/{type}")]public async Task<IActionResult>Report(string type)=>Ok(await ReportRows(type));[HttpGet("reports/{type}/export")]public async Task<IActionResult>Export(string type){var rows=await ReportRows(type);var cols=rows.SelectMany(x=>x.Keys).Distinct().ToList();var csv=new StringBuilder();csv.AppendLine(string.Join(",",cols.Select(Csv)));foreach(var row in rows)csv.AppendLine(string.Join(",",cols.Select(c=>Csv(row.GetValueOrDefault(c)?.ToString()))));return File(Encoding.UTF8.GetBytes(csv.ToString()),"text/csv",$"hr-{type}-{DateTime.UtcNow:yyyyMMdd}.csv");}
 async Task<List<Dictionary<string,object?>>>ReportRows(string type){var p=await People().Include(x=>x.Department).Include(x=>x.Manager).ToListAsync();if(new[]{"employee","manager","headcount","status"}.Contains(type))return p.Where(x=>type!="employee"||x.Role=="Employee").Where(x=>type!="manager"||x.Role=="Manager").Select(x=>new Dictionary<string,object?>{{"Name",x.FullName},{"Code",x.EmployeeCode},{"Role",x.Role},{"Department",x.Department?.Name},{"Manager",x.Manager?.FullName},{"EmploymentStatus",x.EmploymentStatus},{"AccountStatus",x.IsActive?"Active":"Inactive"}}).ToList();if(type=="recruitment")return(await db.Applicants.Where(x=>x.AssignedHrId==HrId()).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Applicant",x.FullName},{"Email",x.Email},{"Status",x.Status},{"Applied",x.AppliedAt}}).ToList();if(type=="onboarding")return(await db.OnboardingRecords.Where(x=>x.AssignedHrId==HrId()).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Candidate",x.CandidateName},{"Status",x.Status},{"Joining",x.JoiningDate}}).ToList();if(type=="offboarding")return(await db.OffboardingRecords.Where(x=>x.AssignedHrId==HrId()).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"UserId",x.UserId},{"Status",x.Status},{"LastWorkingDate",x.LastWorkingDate}}).ToList();if(type=="training")return(await db.TrainingPrograms.Where(x=>x.AssignedHrId==HrId()).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Training",x.Name},{"Code",x.Code},{"Status",x.Status}}).ToList();if(type=="attendance")return(await db.Attendances.Include(x=>x.User).Where(x=>x.User!.AssignedHrId==HrId()).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Person",x.User?.FullName},{"Date",x.AttendanceDate},{"Status",x.AttendanceStatus},{"Hours",x.EffectiveHours},{"LateMinutes",x.LateMinutes}}).ToList();if(type=="leave")return(await db.Leaves.Include(x=>x.User).Where(x=>x.User!.AssignedHrId==HrId()).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"Person",x.User?.FullName},{"Type",x.LeaveType},{"From",x.FromDate},{"To",x.ToDate},{"Status",x.Status}}).ToList();if(type=="performance")return(await db.PerformanceReviews.Where(x=>People(null).Any(u=>u.UserId==x.EmployeeId)).ToListAsync()).Select(x=>new Dictionary<string,object?>{{"EmployeeId",x.EmployeeId},{"Year",x.Year},{"Quarter",x.Quarter},{"Rating",x.Rating},{"Released",x.IsReleased}}).ToList();return new(){new(){{"Report",type},{"OwnedPeople",p.Count},{"GeneratedAt",DateTime.UtcNow}}};}
 static string Csv(string? v){v??="";if(v.Length>0&&"=+-@".Contains(v[0]))v="'"+v;return $"\"{v.Replace("\"","\"\"")}\"";}async Task InvalidateMfa(int id){var xs=await db.MfaChallenges.Where(x=>x.UserId==id&&!x.IsUsed&&x.InvalidatedAt==null).ToListAsync();foreach(var x in xs)x.InvalidatedAt=DateTime.UtcNow;}void Notify(int id,string t,string m,string type,string? url,string key)=>db.Add(new Notification{UserId=id,Title=t,Message=m,Type=type,RelatedUrl=url,DeduplicationKey=key});
 static void Job(RecruitmentJob x,HrRequest r){x.Title=r.Title;x.JobCode=r.JobCode;x.Department=r.Department;x.Designation=r.Designation;x.EmploymentType=r.EmploymentType;x.NumberOfOpenings=Math.Max(1,r.NumberOfOpenings);x.RequiredExperience=r.Experience??"";x.RequiredSkills=r.Skills??"";x.Location=r.Location??"";x.Description=r.Description??"";x.OpeningDate=r.OpeningDate;x.ClosingDate=r.ClosingDate;x.Status=r.Status;}async Task<IActionResult?>InterviewValid(HrRequest r){if(r.EndTime<=r.StartTime)return BadRequest(new{message="End must be after start"});if(!await db.Applicants.AnyAsync(x=>x.ApplicantId==r.ApplicantId&&x.AssignedHrId==HrId()))return NotFound();if(r.InterviewerId.HasValue&&!await db.Users.AnyAsync(x=>x.UserId==r.InterviewerId&&x.IsActive))return BadRequest(new{message="Interviewer inactive"});return null;}static void Interview(Interview x,HrRequest r){x.ApplicantId=r.ApplicantId??0;x.InterviewerId=r.InterviewerId;x.ScheduledAt=r.StartTime;x.EndTime=r.EndTime;x.Mode=r.Mode;x.Location=r.Location??"";x.Status=r.Status;x.Feedback=r.Feedback??"";x.Result=r.Result??"";x.Notes=r.Remarks??"";x.HrRemarks=r.HrRemarks??"";}static void Onboard(OnboardingRecord x,HrRequest r){x.ApplicantId=r.ApplicantId;x.EmployeeId=r.UserId==0?null:r.UserId;x.CandidateName=r.FullName;x.Role=r.Role;x.JoiningDate=r.JoiningDate??DateTime.UtcNow;x.DepartmentId=r.DepartmentId;x.Department=r.Department;x.Designation=r.Designation;x.EmploymentType=r.EmploymentType;x.ManagerId=r.ManagerId;x.OfficialEmail=r.Email;x.EmployeeCode=r.EmployeeCode;x.Checklist=r.Checklist??"";x.Remarks=r.Remarks??"";x.Status=r.Status;}static void Offboard(OffboardingRecord x,HrRequest r){x.UserId=r.UserId;x.ResignationDate=r.ResignationDate;x.LastWorkingDate=r.LastWorkingDate;x.Reason=r.Reason??"";x.ExitType=r.ExitType;x.NoticePeriodDays=r.NoticePeriodDays;x.Status=r.Status;x.Checklist=r.Checklist??"";x.Remarks=r.Remarks??"";}static void Train(TrainingProgram x,HrRequest r){x.Name=r.Title;x.Code=r.Code;x.Description=r.Description??"";x.Trainer=r.Trainer??"";x.DepartmentId=r.DepartmentId;x.StartDate=r.StartTime;x.EndDate=r.EndTime;x.DeliveryMode=r.Mode;x.Location=r.Location??"";x.Status=r.Status;x.Remarks=r.Remarks??"";}
}
public sealed class HrRequest{public int UserId{get;set;}public int?JobId{get;set;}public int?ApplicantId{get;set;}public int?InterviewerId{get;set;}public int?DepartmentId{get;set;}public int?ManagerId{get;set;}public string FullName{get;set;}="";public string Email{get;set;}="";public string Username{get;set;}="";public string Password{get;set;}="";public string Role{get;set;}="Employee";public string EmployeeCode{get;set;}="";public string?PhoneNumber{get;set;}public string Designation{get;set;}="";public string Department{get;set;}="";public string EmploymentType{get;set;}="Full-time";public string EmploymentStatus{get;set;}="Active";public string?Location{get;set;}public DateTime?JoiningDate{get;set;}public bool IsActive{get;set;}=true;public string Title{get;set;}="";public string JobCode{get;set;}="";public string Code{get;set;}="";public string?Description{get;set;}public string?Experience{get;set;}public string?Skills{get;set;}public int NumberOfOpenings{get;set;}=1;public DateTime OpeningDate{get;set;}public DateTime?ClosingDate{get;set;}public string Status{get;set;}="Draft";public string?ResumeUrl{get;set;}public string?Remarks{get;set;}public DateTime StartTime{get;set;}public DateTime EndTime{get;set;}public string Mode{get;set;}="Online";public string?Feedback{get;set;}public string?Result{get;set;}public string?HrRemarks{get;set;}public string?Checklist{get;set;}public DateTime ResignationDate{get;set;}public DateTime LastWorkingDate{get;set;}public string?Reason{get;set;}public string ExitType{get;set;}="Resignation";public int NoticePeriodDays{get;set;}public string?Trainer{get;set;}}